import React from "react";
import {observer} from 'mobx-react';
import {observable} from 'mobx';

@observer
class Button extends React.Component {
    @observable
    _open = false;

    toggle() {
        this._open = !this._open;
        return this._open;
    }

    open() {
        this._open = true;
        return this._open;
    }

    close() {
        this._open = false;
        return this._open;
    }

    isOpen() {
        return this._open;
    }

    render() {
        if (this._open) {
            return <img src="data:image/svg+xml;base64," className="rcw-close-launcher" alt="Open chat"/>
        } else {
            return <img src="data:image/svg+xml;base64,"/>;
        }
    }
}

export default Button;